      "quote": null,
      "reason": "No individuals were reported as contacted to identify studies."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The reference lists of included articles were screened again for additional studies that may have been missed.",
      "reason": "Reference lists of included articles (backward citation searching) were examined, with type specified."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "The nine remaining studies had their reference lists screened and a further four studies were identified and included.",
      "reason": "Backward citation searching of included studies is described, but no citation index/platform or date of the citation searching is reported."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No journals or conference proceedings were reported as separately consulted."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_7",
  "elements": [
    {
      "element_id": "prisma_2020_7_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "We conducted a search on the 2nd of March 2021 across the following databases: PubMed, Embase (Ovid) and the Cochrane Central Register of Controlled Trials (CENTRAL). The search terms used were as follows: 'Prehospital' AND ('Tracheal tube introducer' OR 'Gum elastic bougie' OR 'Flexible tip bougie' OR 'Eschmann tracheal tube introducer' OR 'Frova introducer' OR 'Stylet').",
      "reason": "Databases, date, and search terms are reported, but a single combined search string is given rather than the full database-specific strategies as actually run (e.g., no MeSH terms or field tags for each database)."
    },
    {
      "element_id": "prisma_2020_7_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "No publication date limitations were set.",
      "reason": "The only limit (no date restriction) is described, but it is not justified by explicit reference to the eligibility criteria."
    },
    {
      "element_id": "prisma_2020_7_e3",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "We used the search strategies recommended for the Preferred Reporting Items for Systematic Reviews and Meta-Analysis (PRISMA) statement [11].",
      "reason": "The PRISMA statement is a reporting guideline, not a published search approach or filter; no published search filter or hedge is cited and no adaptations of such filters are described."
    },
    {
      "element_id": "prisma_2020_7_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence that natural-language processing or text-analysis tools were used to identify or refine search terms; the search used a simple hand-built keyword string."
    },
    {
      "element_id": "prisma_2020_7_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence that translation tools were used to translate search strings between sources; the same keyword string appears to have been applied directly."
    },
    {
      "element_id": "prisma_2020_7_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No validation of the search strategy is described anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No peer review of the search strategy (e.g., PRESS) is described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e8",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "'Prehospital' AND ('Tracheal tube introducer' OR 'Gum elastic bougie' OR ... OR 'Stylet')",
      "reason": "The search structure appears concept-based (setting AND device terms) rather than PICO-based, but the conceptual structure and its development are not described."
    }
  ],
  "confidence": 88
}

