{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "The primary outcomes of this systematic review are first pass ETI and overall ETI success. Secondary outcomes include time to ETI, ease-of-use and ETI complications such as oesophageal intubation.",
      "reason": "Outcomes are listed but not explicitly defined; only brief descriptions (e.g. 'ETI complications such as oesophageal intubation') are given."
    },
